-- Short lines of zone lore, keyed by the zone name exactly as the English client shows it.
--
-- RULES for this file:
--   * Every line states something that is true of that zone's lore. No invented places or events.
--   * No generic mood lines. A zone with no entry just gets its title, with no quote.
--   * Zones with the same name in two eras (Nagrand, Shadowmoon Valley) are left out on purpose.
--   * {zone} is replaced with the zone name.
-- If a line is wrong, fix or delete it. Please check any new line against the game before adding it.

local _, ns = ...

