    "Lore: The Dark Portal slowly withered the land, leaving the south parched and barren.",
    "Trivia: The Black Morass was originally planned as a zone, not only a dungeon.",
    "Trivia: Early WoW map sketches showed the Black Morass beneath Blackrock Spire.",
    "Note: Enter the Black Morass instance via the Caverns of Time event.",
},
["The Mechanar"] = {
    "Lore: The Mechanar is the first wing of Tempest Keep.",
    "Lore: The naaru created Tempest Keep, and the Mechanar once belonged to them.",
    "Lore: Kael'thas made the Mechanar a factory for power.",
    "Lore: Pathaleon the Calculator is Kael'thas's chief planner.",
    "Lore: Kael'thas chose the Mechanar as a factory to generate large amounts of power.",
    "Lore: Pathaleon the Calculator commands blood elves guarding stored manacells in the Mechanar.",
    "Lore: Ethereals smuggle Mechanar manacells to the Sunwell to fuel Kil'jaeden's summoning.",
    "Lore: Mechano-Lord Capacitus appears to create the power using naaru technology from Tempest Keep.",
    "Trivia: The Mechanar was originally meant to be themed after a factory.",
    "Note: The Mechanar is the purple crystal building south of the main palace.",
    "Note: Killing both named elites on the first level opens the elevator.",
},
["The Botanica"] = {
    "Lore: The Botanica is the second wing of Tempest Keep.",
    "Lore: The naaru used the Botanica to safeguard unusual wildlife.",
    "Lore: Kael'thas's blood elves study Outland's plant life in the Botanica.",
    "Lore: Commander Sarannis is Kael'thas's commander at the Botanica.",
    "Lore: The naaru once gathered Outland wildlife samples here behind special safeguards.",
    "Lore: Kael'thas and his blood elves seized Tempest Keep from the naaru.",
    "Lore: Blood elf scientists now experiment on Outland flora and naaru technology.",
    "Lore: Thalassian trees from Quel'Thalas have been grown here with boosted growth.",
    "Trivia: The Botanica was originally meant to be themed after an atrium with a garden shed.",
    "Note: All Botanica bosses are optional, so you can reach Warp Splinter without killing them.",
    "Note: The Botanica sits directly north of the main palace in Tempest Keep.",
},
["The Arcatraz"] = {
    "Lore: The Arcatraz is a naaru prison for dangerous beings.",
    "Lore: The Sha'tar historically ran the Arcatraz.",
    "Lore: Harbinger Skyriss, an Old God servant, caused the prison break.",
    "Lore: Harbinger Skyriss corrupted Warden Mellichar.",
    "Lore: The Arcatraz is the third wing of Tempest Keep in Netherstorm.",
    "Lore: The Sha'tar used the Arcatraz to imprison the most dangerous beings they encountered.",
    "Lore: Kael'thas sent a warden and guards to the Arcatraz after seizing Tempest Keep.",
    "Lore: Harbinger Skyriss corrupted Warden Mellichar, who then freed many prisoners.",
    "Lore: Legion forces tried to free High Inquisitor Raalgar from the Arcatraz.",
    "Trivia: The name references Alcatraz, the island prison near San Francisco.",
    "Note: Every group member needs a flying mount or flying form to reach the entrance.",
},
["Scarlet Halls"] = {
    "Lore: Scarlet Halls is one of two new wings of the Scarlet Monastery.",
    "Lore: The Scarlet Crusade's veterans are preparing an army inside the Halls.",
    "Lore: Flameweaver Koegler waits in the Athenaeum.",
    "Lore: Scarlet Halls combines the former Armory and Library wings of Scarlet Monastery.",
    "Lore: Its soldiers are the Crusade's fiercest warriors, bound by hatred of the unliving.",
    "Lore: Flameweaver Koegler is the final boss of Scarlet Halls.",
    "Note: The bosses are Houndmaster Braun, Armsmaster Harlan and Flameweaver Koegler.",
    "Note: Its sub-regions include the Athenaeum, Huntsman's Cloister and Gallery of Treasures.",
},
["Shado-Pan Monastery"] = {
    "Lore: The Shado-Pan Monastery is a mountain retreat in Kun-Lai Summit.",
    "Lore: The Shado-Pan Monastery is the home and training ground of the Shado-Pan.",
    "Lore: Taran Zhu, the Shado-Pan leader, fell under the Sha of Hatred's control.",
    "Lore: The Sha of Violence, Hatred and Anger broke free of their prisons.",
    "Lore: The Sha were set free and threaten the Shado-Pan's base of operations.",
    "Lore: Chen Stormstout brought a wounded Vol'jin here to recuperate during the Landfall.",
    "Lore: Zandalari trolls and mogu allies, led by Khal'ak, later invaded the monastery.",
    "Lore: Early monks reportedly planned their overthrow of the mogu at this location.",
    "Trivia: The monastery is implied to be on or near the Peak of Serenity.",
    "Note: A path from Neverest Basecamp, skirting Mount Neverest's north, also leads here.",
},
["Siege of Niuzao Temple"] = {
    "Lore: Niuzao Temple spans two fortified islands beyond the Serpent's Spine.",
    "Lore: Pandaren defenders long guarded the bridges linking the two isles.",
    "Lore: The mantid seized one island by surprise.",
    "Lore: Mantid built a bridge from a massive tree root to seize one island.",
    "Lore: Pandaren defenders guarded the narrow bridges between the islands for years.",
    "Lore: Yang Ironclaw, Li Chu and Lo Chu are Shado-Pan soldiers at the top.",
    "Note: Vizier Jin'bak, an alchemist, is met on the ramp up to the temple.",
    "Note: Wing Leader Ner'onok waits at the bridge's end as the final boss.",
},
["Stormstout Brewery"] = {
    "Lore: The Stormstout Brewery is the ancestral home of the Stormstout family.",
    "Lore: Uncle Gao managed the brewery while the Stormstouts were away.",
    "Lore: Virmen, hozen and alementals overran the brewery.",
    "Lore: Chen Stormstout returned to reconnect with his relatives.",
    "Lore: Uncle Gao's poor management let virmen and hozen overrun the brewery.",
    "Lore: Brewmaster Blanche was murdered here during the third Burning Legion invasion.",
    "Lore: Monks of the Order of the Broken Temple later defeated the Legion within the brewery.",
    "Lore: Zouchin refugees later stayed at the brewery after a Zandalari attack.",
    "Trivia: Stormstout Brewery was the third announced five-man dungeon of Mists of Pandaria.",
    "Trivia: Chen discovers Auntie Stormstout's ghost cookies are not filling at all.",
    "Note: Ook-Ook's fight starts only after defeating 40 partying hozen.",
    "Note: Defeating Hoptallus moves the blocking carrot, opening the path to the distillery.",
},
["Temple of the Jade Serpent"] = {
    "Lore: The Temple of the Jade Serpent honors the spirit of wisdom.",
    "Lore: Emperor Shaohao trapped the Sha of Doubt here.",
    "Lore: The jinyu consider the temple sacred.",
    "Lore: The Order of the Cloud Serpent guards the temple.",
    "Lore: The jinyu use the temple's scrying pool as eyes and ears across Pandaria.",
    "Lore: Shaohao trapped the Sha of Doubt in this temple long ago.",
    "Lore: Li Li Stormstout noted all races were welcomed here to meditate.",
    "Trivia: The temple is also called the Jade Temple and the East Temple.",
    "Note: Go left at the first crossroads to meet Wise Mari.",
},
["Mogu'shan Vaults"] = {
    "Lore: The Mogu'shan Vaults are a mogu archive in northeast Kun-Lai Summit.",
    "Lore: The mogu stored records of their accomplishments in the vaults.",
    "Lore: Elegon, a celestial cloud serpent, protects Titan technology here.",
    "Lore: The Spirit Kings are vengeful spirits of dead mogu rulers.",
    "Lore: The Vaults hold records of the mogu's accomplishments, guarded by ferocious magical beings.",
    "Lore: Lei Shen's giant construct, Will of the Emperor, was built to raise his armies.",
    "Lore: Lorewalker Cho's button press in a hall of deceased rulers awakens the Spirit Kings.",
    "Lore: Magni Bronzebeard and an adventurer found the vaults overrun by mantid and Void tentacles.",
    "Note: The entrance lies in northeast Kun-Lai Summit, accessed from Mogu'shan Terrace.",
    "Note: Elegon guards Titan technology deeper inside the vaults.",
},
["Heart of Fear"] = {
    "Lore: Heart of Fear is the seat of the mantid dominion.",
    "Lore: Grand Empress Shek'zeer rules while possessed by the Sha of Fear.",
    "Lore: The Klaxxi turned against Shek'zeer.",
    "Lore: Garalon is the mightiest of the mantid Kunchong.",
    "Lore: The Sha of Fear corrupted Shek'zeer, driving the Klaxxi to seek outside help.",
    "Lore: The Sha of Fear fled Shek'zeer's death, later hunted at Terrace of Endless Spring.",
    "Note: The entrance sits at the base of a rotting tree in western Dread Wastes.",
    "Note: Destroying Garalon's legs weakens it, which is how adventurers killed it.",
},
["Terrace of Endless Spring"] = {
    "Lore: The Terrace of Endless Spring lies at the midpoint of the Veiled Stair.",
    "Lore: Emperor Shaohao performed a ritual here to summon the mists.",
    "Lore: Tian Monastery monks stored Shaohao's staff, Sheilun, here.",
    "Lore: The Sha of Fear fled here after leaving the Heart of Fear.",
    "Lore: Emperor Shaohao's ritual here summoned the mists that saved Pandaria from the Great Sundering.",
    "Lore: Champions cleansed the terrace and defeated the Sha of Fear after Shek'zeer's death.",
    "Lore: The Legion attacked the Terrace during the third invasion, but the Shado-Pan protected it.",
    "Trivia: Beta files once referred to the terrace as Terrace of Eternity.",
    "Note: The Terrace sits midway along the Veiled Stair, a mountain pass.",
    "Note: Defeating Lei Shi frees a water spirit that clears the Sha's fog.",
},
["Throne of Thunder"] = {
    "Lore: The Throne of Thunder is a citadel on the Isle of Thunder.",
    "Lore: Lei Shen took the name Thunder King and made the mountain his seat.",
    "Lore: Lei Shen found Ra-den, a titanic watcher, guarding the Engine of Nalak'sha.",
    "Lore: Lei Shen has been resurrected and allied with the Zandalari.",
    "Lore: Lei Shen reportedly tore out Ra-den's heart, gaining power over wind and storm.",
    "Lore: Lei Shen declared the Thundering Mountain his seat of power, building a forbidden city atop it.",
    "Lore: A mogu successor later moved the empire's capital to Mogu'shan Palace.",
    "Lore: The Shado-Pan Assault seeks to defeat Lei Shen once and for all.",
    "Note: Portals from Townlong Steppes faction camps lead to the Isle of Thunder.",
    "Note: A sewer grate in Bleak Hollow teleports adventurers to the inner courtyard.",
},
["Siege of Orgrimmar"] = {
    "Lore: The Siege of Orgrimmar was fought in 30 ADP to end Garrosh's rule.",
    "Lore: Varian Wrynn and Vol'jin led the Alliance and the Darkspear Rebellion.",
    "Lore: Garrosh Hellscream led the True Horde in Orgrimmar.",
    "Lore: Vol'jin became Warchief after the siege.",
    "Lore: Garrosh Hellscream was deposed and succeeded by Vol'jin as Warchief.",
    "Lore: The siege concluded the Alliance-Horde war that began before the Cataclysm.",
    "Lore: Garrosh was spared by Taran Zhu and sent to stand trial in Pandaria.",
    "Lore: Garrosh escaped after his defeat and instigated the war in Draenor.",
    "Lore: Thrall tried to execute Garrosh, but Varian stopped him.",
    "Lore: Garrosh was bolstered by goblin mercenaries, mantid allies and Y'Shaarj's power.",
    "Lore: General Nazgrim died defending the last barrier before Garrosh's Underhold.",
    "Lore: Garrosh used the Vale's pools to revive the Heart of Y'Shaarj.",
    "Trivia: Dave Kosak said Dalaran was planned to hover above Orgrimmar but was scrapped.",
    "Trivia: Overwatch's Blizzard World features the siege as an in-universe attraction.",
},

["Ruins of Gilneas"] = {
    "Lore: King Genn Greymane raised the Greymane Wall, finished before the Third War.",
    "Lore: Archmage Arugal unleashed worgen from the Emerald Dream against the Scourge.",
    "Lore: The Cataclysm breached the Greymane Wall, and the Forsaken invaded by land and sea.",
    "Lore: The Scarlet Crusade later held Gilneas City, until it was driven out.",
    "Lore: Lord Hiram Creed secretly led the Blackhowl and was revealed as a black dragonflight member.",
    "Trivia: The peninsula appears on maps going back to Warcraft II and Warcraft III.",
    "Note: There are no flight paths here. Shadowfang Keep's Meeting Stone is the fastest route in.",
    "Note: The nearest Horde flight paths are in Silverpine Forest and Hillsbrad Foothills.",
},
["Alterac Mountains"] = {
    "Lore: The human Alteraci tribe lived in these peaks before Arathor rose.",
    "Lore: The city-state of Alterac arose here as Arathor fractured.",
    "Lore: Crushridge ogres under Mug'thol claimed the ruins of Alterac City.",
    "Lore: Aliden Perenolde, Alterac's former prince, founded the Syndicate during the Third War.",
    "Lore: The Horde retook Alterac City and Strahnbrad during the Fourth War.",
    "Trivia: The mountains appear in the South Park episode Make Love, Not Warcraft.",
    "Trivia: Galvan the Ancient is said to have spent a decade here learning to forge truesilver.",
    "Note: Stormpike Guard and Frostwolf clan face off near the entrances to Alterac Valley.",
    "Note: Wintersbite, a rare herb, grows in these mountains.",
    "Note: Fans have guessed the Red Caverns lie somewhere in the Alterac range.",
},
["Tol Barad Peninsula"] = {
    "Lore: Kul Tiras, Dalaran and Stromgarde have each held Tol Barad in the past.",
    "Lore: Rustberg Village, Farson Hold and Wellson Shipyard are its major settlements.",
    "Lore: Baradin's Wardens and Hellscream's Reach run the daily quest hubs.",
    "Trivia: Despite the name, the peninsula is really two large islands split by a small channel.",
    "Trivia: Tol Barad Peninsula arrived with patch 4.0.3a in November 2010.",
    "Note: Portals from Stormwind and Orgrimmar lead to Baradin Base Camp and Hellscream's Grasp.",
    "Note: Elementium Ore, Cinderbloom and Fathom Eel can all be gathered here.",
    "Note: A random selection of the daily quests appears each day.",
},
["Nightmare Grove"] = {
    "Lore: Four dragons of the Nightmare wait here: Emeriss, Lethon, Taerar and Ysondre.",
    "Note: Portals in Ashenvale, Duskwood, Feralas and the Hinterlands lead into the raid.",
    "Note: The portal you enter by decides which dragon you meet first.",
    "Note: Defeating a dragon opens a portal straight to the next one.",
},
["Maelstrom"] = {
    "Lore: The Well of Eternity collapsed in the Great Sundering, and the Maelstrom formed over it.",
    "Lore: The capital Zin-Azshari was dragged under, becoming Nazjatar.",
    "Lore: Deathwing used the Maelstrom to return from Deepholm and trigger the Cataclysm.",
    "Lore: Thrall and the Earthen Ring shamans tried to hold the rift together.",
    "Lore: An Azerite wound erupted here during the Fourth War, freeing rampaging elementals.",
    "Lore: The Earthen Ring still watches over the Maelstrom today.",
    "Trivia: Epicus Maximus, a shark-dinosaur-Forsaken, was a Cataclysm beta oddity here.",
    "Trivia: Shen-zin Su, the Wandering Isle, was spiraling toward the Maelstrom before it was wounded.",
    "Note: Mounting is disabled here, and an invisible wall confines you to one area.",
    "Note: The Maelstrom is a sanctuary, so PvP combat is disabled.",
    "Note: Ships and zeppelins route around it to avoid its dangerous waters.",
},
["Cen'gar"] = {
    "Lore: Cen'gar is a world of lava and molten rock, much like the Firelands.",
    "Lore: The Burning Legion is corrupting its fire elementals.",
    "Lore: Emblazoned Fire Tamers are eredar trying to bend the elementals to the Legion.",
    "Lore: Magma Giants roam the molten terrain.",
    "Trivia: Cen'gar was added in patch 7.3.0 on August 29, 2017.",
    "Note: In Legion, an Invasion Point linked Argus to Cen'gar.",
},
["Naigtal"] = {
    "Lore: Naigtal means endless stars on water in the local language.",
    "Lore: It is a world of giant mushrooms, much like Zangarmarsh on Outland.",
    "Lore: The draenei fled the Legion and settled here, calling their home Teloru'vil.",
    "Lore: Unsaalvei brokered peace between the draenei and the native people of Naigtal.",
    "Lore: Sergeant Krashj hails from Naigtal and trained Marsh Shamblers for pit combat.",
    "Trivia: Naigtal first appeared as an Invasion Point, then returned as a Showdown location.",
    "Trivia: Vilaldoun, a draenei mausoleum on Naigtal, echoes Auchindoun.",
    "Note: Energized Vines zap anything nearby, so keep your distance.",
},
["Aurinor"] = {
    "Lore: Aurinor is a world of blue grass and trees on floating islands.",
    "Lore: Clouds lie far below the islands, with seemingly nothing under them.",
    "Lore: Strange temporal anomalies appear on the islands of Aurinor.",
    "Lore: Its landscape resembles Shadowmoon Valley before Draenor was shattered.",
    "Trivia: The Shattered Grove reuses Aurinor's map geometry.",
    "Trivia: Aurinor was added in patch 7.3.0 on August 29, 2017.",
    "Note: Aurinor has both a standard Invasion Point and a Greater Invasion Point.",
    "Note: Small blue lights drift through the air, perhaps magic, perhaps insects.",
},
["Sangua"] = {
    "Lore: Sangua is a world of bones and dust around a lake of blood.",
    "Lore: Demons drain the blood lake, and destroying Blood Drainers makes something stir below.",
    "Lore: Huge rib bones and spines hint that a giant creature once roamed here.",
    "Trivia: The blood lake setting recalls Sethekk Hollow on Draenor.",
    "Trivia: Sangua's map was reused for Frachtorn.",
    "Trivia: Sangua was added in patch 7.3.0 on August 29, 2017.",
    "Note: Fans have wondered if the creature beneath the lake is an Old God.",
},
["Bonich"] = {
    "Lore: Bonich is a misty world of massive conifers around an open meadow.",
    "Lore: The Burning Legion wants to strip Bonich's forests of their resources.",
    "Lore: The Eternal Conservators here appear to be dryads.",
    "Trivia: Bonich's deer shed their antlers, just as the deer of Azeroth do.",
    "Trivia: A statue in the brush resembles those in Azeroth's troll ruins.",
    "Note: Elkeirnir is a larger, darker, named stag among the Redwood Guardians.",
    "Note: Sacred vines entangle anything that wanders too close.",
},
["Korthia"] = {
    "Lore: Korthia was lost in the In-Between until the Jailer dragged it into the Maw.",
    "Lore: The Jailer searches Korthia for First Ones secrets to feed his twisted vision.",
    "Lore: Korthia was hidden to keep its secrets from people like the Jailer.",
    "Lore: Archivist Roh-Suir rules Korthia and wields a Lodestaff that finds any artifact.",
    "Lore: The Primus entrusted his sigil to Korthia before the Jailer took him.",
    "Trivia: The name Korthia may echo Kur, the Sumerian and Akkadian underworld.",
    "Trivia: Korthia arrived with patch 9.1.0 in June 2021.",
    "Note: Reach Korthia through the Beastwarrens in the Maw, southeast of Desmotaeron.",
    "Note: A Waystone in Keeper's Respite links Korthia back to Oribos.",
    "Note: Ten one-time treasures across Korthia and Desmotaeron count toward Treasures of Korthia.",
},
["Darnassus"] = {
    "Lore: Darnassus was the night elf capital, in western Teldrassil.",
    "Lore: Tyrande Whisperwind ruled from the Temple of the Moon as High Priestess.",
    "Lore: Fandral Staghelm led the druids who planted Teldrassil after the Third War.",
    "Lore: Darnassus was destroyed in the Burning of Teldrassil.",
    "Lore: Survivors of Darnassus moved to Stormwind City after its fall.",
    "Lore: Gilnean refugees were welcomed here, and the Howling Oak was grown for them.",
    "Trivia: Chris Metzen said Darnassus blends Nordic and Japanese influences.",
    "Trivia: Several Darnassus towers resemble the pagoda at Yakushi-ji in Nara, Japan.",
    "Trivia: A Darnassus card back in Hearthstone was a reward for reaching Rank 20.",
    "Note: Use the Rut'theran Village portal instead of the nearly two-minute flight.",
    "Note: The Bough of the Eternals on the Temple Gardens island holds the bank.",
},
["Stormshield"] = {
    "Lore: Stormshield is the Alliance's main base on Draenor, at the south end of Ashran.",
    "Lore: Stormshield Stronghold guards it, the Alliance's main keep inside Ashran.",
    "Lore: Grand Marshal Tremblade rules Stormshield, which stands with Wrynn's Vanguard.",
    "Lore: Its Horde counterpart, Warspear, lies at Ashran's north end.",
    "Note: Portals connect Stormshield to Lion's Watch and Stormwind City.",
    "Note: Honor and Conquest vendors stand near Ashran's exit.",
},
["Warspear"] = {
    "Lore: Warspear is the Horde's main base on Draenor, at Ashran's north end.",
    "Lore: High Warlord Volrath rules Warspear, which stands with Vol'jin's Spear.",
    "Lore: Warspear Outpost guards the town from just outside the main PvP zone.",
    "Lore: Its Alliance counterpart, Stormshield, lies at Ashran's south end.",
    "Trivia: Warspear arrived with patch 6.0.2 in Warlords of Draenor.",
    "Note: Lieutenant Brokefist sells Honor gear and Lieutenant Axelash sells Conquest gear.",
    "Note: The Orgrimmar portal is still listed as a travel connection.",
},
["Bel'ameth"] = {
    "Lore: Bel'ameth means Arms of the Goddess in Darnassian.",
    "Lore: Bel'ameth is the new capital city of the Alliance night elves.",
    "Lore: Its moonwell holds the last waters saved from the Temple of the Moon.",
    "Lore: It was founded after Amirdrassil bloomed in 40 ADP.",
    "Lore: Malfurion and Tyrande named Shandris Feathermoon the new leader of the night elves.",
    "Lore: Lor'themar Theron, Thalyssra and Umbric sought aid here to retake the Sunwell.",
    "Trivia: Bel'ameth crafters are known for dream-inspired designs.",
    "Trivia: Ainderu Summerleaf's hand-woven flying quilts are popular with the city's children.",
    "Note: Bel'ameth sits under the central tree of open-world Amirdrassil.",
    "Note: Fly west out of Ohn'ahran Plains to reach Amirdrassil.",
    "Note: The portal to Stormwind's Wizard's Sanctum is Alliance only.",
    "Note: Druids can take a rootway from here to the Emerald Dreamway.",
},
["Val"] = {
    "Lore: Val is a world of ice-covered valleys and billowing storms.",
    "Lore: Enormous hailstorms shield Val and can tear through Legion ships.",
    "Lore: Far below freezing, exposure here can kill within seconds.",
    "Lore: Legion soldiers sent to Val were often being punished, and they loathed it.",
    "Lore: Demons placed braziers to keep the cold bearable and held prisoners here.",
    "Lore: Inquisitors interrogated captives on Val to steal their secrets.",
    "Lore: Illidari sent to Val were left frozen in place until adventurers freed them.",
    "Trivia: The first PTR build to introduce Invasion Points called this world Val Sholoth.",
    "Note: Fans have guessed Chill's Reach reuses Val's map and may be the same place.",
},
["Lunarfall"] = {
    "Trivia: The grove where Lunarfall stood became Shadowmoon Village in the main timeline.",
},
["Frostwall"] = {
    "Lore: Frostwall is the Horde garrison in Frostfire Ridge.",
    "Lore: Lunarfall, in Shadowmoon Valley, is its Alliance counterpart.",
    "Lore: A fully upgraded Frostwall is considered a fortress.",
    "Note: Flight masters wait at Bladespire Citadel, Stonefang Outpost and Wor'gol.",
    "Note: Frostwall's portal connects to Warspear.",
    "Note: Garrison visitors appear only after you have met them first.",
},
["Shrine of Seven Stars"] = {
    "Lore: The Shrine of Seven Stars is an ancient mogu structure south of Mogu'shan Palace.",
    "Lore: The Alliance claimed it and made it their main hub in Pandaria.",
    "Lore: Its Horde counterpart, the Shrine of Two Moons, lies opposite Mogu'shan Palace.",
    "Lore: In the Vale of Eternal Twilight, it is the last unconquered shrine.",
    "Lore: The Shrine of Two Moons fell to the Black Empire in the twisted Vale.",
    "Trivia: During early beta, the shrine was named The Star's Ascent.",
    "Note: The Summer Terrace holds the flight master and the Spirit of Harmony vendor.",
    "Note: The upper level offers a bank, transmogrification and item upgrades.",
    "Note: Gleep Chatterswitch teleports Alliance players to Ratchet for 10 gold.",
},
["Shrine of Two Moons"] = {
    "Lore: The Shrine of Two Moons is an ancient mogu structure north of Mogu'shan Palace.",
    "Lore: The Golden Lotus allowed the Horde to use the shrine as its Pandaria hub.",
    "Lore: Sunwalker Dezco is the shrine's de facto ruler.",
    "Trivia: During early beta, the shrine was named White Moon Shrine.",
    "Note: Its Alliance counterpart, the Shrine of Seven Stars, sits across Mogu'shan Palace.",
    "Note: The upper Golden Terrace holds the flight master and the riding trainer.",
    "Note: The Hall of Secrets offers transmogrification, reforging and void storage.",
    "Note: There is no general auction house here, only one serving engineers.",
},
["Founder's Point"] = {
    "Lore: Faldir's Arathi migrants settled Founder's Point around 1,200 BDP.",
    "Lore: Its fields and orchards predate the founding of Stormwind City.",
    "Lore: Faldir's Torch is the first light seen by ships bound for Stormwind Harbor.",
    "Lore: An amnesiac dwarf washed ashore here and built a bridge on Stoneveil Ridge.",
    "Lore: Jorvan Longmoor's ancestors built the first houses on the island.",
    "Lore: Its landscape blends Elwynn Forest, Westfall and Duskwood.",
    "Lore: Its Horde counterpart is Razorwind Shores.",
    "Note: Gryphon flocks roost at the Small Aerie on the island.",
    "Note: Reach it by portal from the Wizard's Sanctum in Stormwind City.",
},
["Razorwind Shores"] = {
    "Lore: Razorwind Shores is a Horde neighborhood zone off the coast of Durotar.",
    "Lore: Its biomes blend Durotar's windswept bluffs, Echo Isles beaches and Azshara's autumn forests.",
    "Lore: Its Alliance counterpart is Founder's Point.",
    "Trivia: It shares its name with Razorwind Canyon in Durotar.",
    "Trivia: Warcraft III: The Frozen Throne used razorwinds for Durotar's strong desert winds.",
    "Trivia: Thrall warns in To Tame a Land that razorwinds will tear roofs off.",
    "Note: A portal in the Pathfinder's Den in Orgrimmar leads here.",
    "Note: Right-click a party member's portrait to view their house, if they own one.",
},
["Lower Blackrock Spire"] = {
    "Lore: Lower Blackrock Spire housed much of the Dark Horde as a sprawling barracks.",
    "Lore: Overlord Wyrmthalak ruled the spire's soldiers as their taskmaster.",
    "Lore: Draconic armies allied with Warchief Rend Blackhand and now lord over the spire.",
    "Lore: Dark Iron dwarves carved the spire into the fiery heart of Blackrock Mountain.",
    "Lore: It was part of the larger Blackrock Spire until patch 6.0.2.",
    "Lore: The player cap fell from fifteen to five over several patches.",
    "Trivia: Author John Staats said the instance was his tribute to Mines of Moria.",
    "Note: The entrance lies south of the Hall of Blackhand, across from Upper Blackrock Spire.",
    "Note: Overlord Wyrmthalak is the final boss.",
    "Note: Rares such as Burning Felguard and Ghok Bashguud appear in Hordemar City.",
},
["Upper Blackrock Spire"] = {
    "Lore: Upper Blackrock Spire is the upper section of the Blackrock Spire complex.",
    "Lore: Warlord Zaela led the Iron Horde's Ironmarch expedition here.",
    "Lore: Zaela was one of Garrosh's staunchest supporters.",
    "Lore: Nefarian's black dragonflight and the Dark Horde once held the Spire.",
    "Lore: The Dark Iron clan carved the fortress into Blackrock Mountain centuries ago.",
    "Lore: The Iron Horde built a doomsday weapon deep within Blackrock Mountain.",
    "Note: Muradin Bronzebeard and High Overlord Saurfang give the faction quests here.",
    "Note: The Blackrock Stadium gauntlet has three waves before the Ragewing fight.",
},
["Demon Fall Canyon"] = {
    "Lore: Demon Fall Canyon is a fel-corrupted canyon in Ashenvale, south of Felfire Hill.",
    "Lore: Grom Hellscream died in the explosion that followed Mannoroth's death.",
    "Lore: Orcs made pilgrimages here to honor Grom, who freed them from the Legion's curse.",
    "Lore: A monument to Grom Hellscream was raised in the canyon in his memory.",
    "Lore: Zekhan's report after the Fourth War says Mannoroth's weapon still hovers here.",
    "Note: Many hostile lesser demons now live in the canyon.",
    "Note: The canyon lies just east of Demon Fall Ridge.",
},
["Storm Cliffs"] = {
    "Lore: The Spitelash naga have taken up residence in the Storm Cliffs.",
    "Note: Storm Cliffs lie directly east of the Southern Rocketway Terminus in Azshara.",
    "Note: The Ravencrest Monument stands at the far east of the cliffs.",
    "Trivia: Storm Cliffs was added in patch 4.0.3a on November 23, 2010.",
},
["Tainted Scar"] = {
    "Lore: The Dark Portal's energies turned the Tainted Scar into a blood-colored, waterless wasteland.",
    "Lore: Lord Kazzak led remaining Burning Legion forces here after Mount Hyjal.",
    "Lore: Razelikh the Defiler was ordered by Kazzak to secure the land.",
    "Lore: Kruul took control of the Scar while Kazzak commanded forces in Outland.",
    "Lore: Daio the Decrepit settled at the Scar's altar to train young recruits.",
    "Lore: Marl Wormthorn's great tree Maldraz was corrupted by nathrezim, birthing the Tainted Forest.",
    "Lore: Rohan Sunveil's Reliquary studied demonic artifacts hidden in the Scar.",
    "Lore: Lord Banehollow retreated here after being exposed at the Darkmoon Faire.",
    "Note: Narixxus the Doombringer occasionally appears behind the altar.",
    "Trivia: The Warcraft II manual described the area's blood-colored soil and demonic beasts.",
},
["Old Hillsbrad Foothills"] = {
    "Lore: Old Hillsbrad Foothills is the setting of the instance Escape from Durnholde Keep.",
    "Lore: The setting is two years before Warcraft III.",
    "Lore: Thrall is held as a slave by Aedelas Blackmoore at Durnholde Keep.",
    "Lore: Future Scarlet Monastery bosses meet at the Southshore inn.",
    "Lore: Tirion Fordring appears as a young man at the Southshore inn meeting.",
    "Lore: Young Kel'Thuzad, still human, walks the road north of Southshore.",
    "Lore: Sally Whitemane and Renault Mograine play tag around the Southshore inn.",
    "Note: Erozion at the cave exit gives the quest to rescue Thrall.",
    "Note: Don Carlos patrols the road between Southshore and Tarren Mill.",
    "Trivia: Before The Burning Crusade, this instance shared its map with the Black Morass.",
},
["Nagrand (Outland)"] = {
    "Lore: Nagrand was sacred to orcs, who held the Kosh'harg celebrations here twice yearly.",
    "Lore: Gul'dan introduced orcs to warlock magic in Nagrand, in the shadow of Oshu'gun.",
    "Lore: The Bonechewer orcs later moved here, to land that had largely escaped fel corruption.",
    "Lore: The region became known as mag'har, meaning uncorrupted.",
    "Lore: Thrall and Varok reunited in Nagrand during the Fourth War.",
    "Lore: The Gorian Empire, the orcs' mortal enemy, once ruled from Highmaul in western Nagrand.",
    "Lore: One of Magtheridon's dimensional gateways stood at the Twilight Ridge.",
    "Lore: Mag'har orcs and Broken draenei Kurenai make their home here today.",
    "Trivia: Nagrand is the only Outland zone without a dungeon or raid.",
    "Trivia: Nagrand's floating islands were inspired by the 1984 film The NeverEnding Story.",
    "Trivia: The zone's music quotes the recitative from Mozart's opera The Magic Flute.",
    "Trivia: Grain grows in Nagrand but crumbles when touched, likely due to Outland's decline.",
    "Note: Halaa is constantly under siege, and its controlling faction gains a region-wide damage buff.",
},
["Shadowmoon Valley (Outland)"] = {
    "Lore: Shadowmoon Valley was once a lush moor lit by Draenor's two moons.",
    "Lore: Orcs formed the Shadowmoon clan about 800 years before the First War.",
    "Lore: Draenei crash-landed on Draenor aboard the Genedar and built the Temple of Karabor.",
    "Lore: After the Horde's assault, the Temple of Karabor was renamed the Black Temple.",
    "Lore: Illidan Stormrage claimed the Black Temple as Illidari headquarters after defeating Magtheridon.",
    "Trivia: Its map alone shows no stars in the Twisting Nether.",
    "Trivia: A Hearthstone card back was themed after Shadowmoon Valley.",
    "Note: The Black Temple raid sits here, among several elite areas.",
    "Note: Most Nightmare Vines grow here, and this was once their only location.",
},
["Nagrand (Draenor)"] = {
    "Lore: Nagrand means Land of Winds in Orcish, and was a Frostwolf homeland.",
    "Lore: The Kosh'harg celebrations were held twice yearly at the base of Oshu'gun.",
    "Lore: The Warsong clan claimed Nagrand but faced occasional ogre raids.",
    "Lore: Imperator Mar'gok rules from Highmaul, allied with the Iron Horde out of necessity.",
    "Lore: Ogres hold the south, seeking to dominate the land and its orc inhabitants.",
    "Note: Frostwolf orcs migrate seasonally, but spend most of their time in Frostfire Ridge.",
    "Note: An abandoned airship base lies south of Nagrand.",
    "Note: The Black Market moved from the Veiled Stair into the Ring of Blood here.",
    "Note: Highmaul is the zone's only instance.",
    "Note: Oshu'gun's otherworldly crystals draw questers and fortune-seekers from across Draenor.",
},
["Shadowmoon Valley (Draenor)"] = {
    "Lore: Shadowmoon Valley is a draenei center, and its heart is the temple of Karabor.",
    "Lore: The Shadowmoon clan under Ner'zhul turned to void magic and necromancy.",
    "Lore: Velen sacrificed himself at Light's Fall to stop the Dark Star.",
    "Lore: The Dark Star was in fact K'ara, a naaru ejected from the Genedar.",
    "Lore: The Shadowmoon Exiles split from their clan, seeking peace with the draenei.",
    "Trivia: Shadowmoon Valley is known for its deep crystal mines.",
    "Note: Tanaan Jungle connects to Shadowmoon Valley by swimming through the Tanaan Channel.",
    "Note: Shadowmoon Burial Grounds is a five-player dungeon within Anguish Fortress.",
    "Note: The valley is contested territory for PvP.",
},
["Drak'Tharon Keep"] = {
    "Lore: Drak'Tharon Keep is an old ice troll fortress bordering Zul'Drak.",
    "Lore: A traitor troll named Drakuru helped the Scourge seize the intact fortress.",
    "Lore: The Scourge used the keep as a base to invade Zul'Drak.",
    "Lore: Its former leader, Prophet Tharon'ja, was transformed into a skeletal wind serpent.",
    "Lore: Mal'Ganis's base during the Third War lay near Drak'Tharon Keep.",
    "Note: Four bosses wait inside: Trollgore, Novos the Summoner, King Dred and The Prophet Tharon'ja.",
    "Note: Crowd-control the Risen Drakkari Handler to fight only its rider, not the mount.",
},
["Gundrak"] = {
    "Lore: Gundrak is the capital of the ice troll Drakkari Empire in eastern Northrend.",
    "Lore: The high prophets Gal'darah, Moorabi and Slad'ran were felled by adventurers.",
    "Lore: The Drakkari sacrificed their loa gods in a desperate bid to survive the Scourge.",
    "Lore: The prophet of Akali drank the rhino god's blood and usurped his power.",
    "Trivia: Gundrak is also spelled Gun'Drak, and breaks the usual troll capital naming pattern.",
    "Trivia: Its central temple city was renamed Atal'Aman when Zul'Aman became a full zone.",
    "Note: The northern entrance meets Slad'ran first, while the southern entrance meets Moorabi first.",
    "Note: Once the three aspect bosses fall, a bridge extends across the circle.",
    "Note: After Eck, swimming through his pool leads straight to the final boss.",
    "Note: Eck the Ferocious is fought only on heroic difficulty.",
},
["Assault on Violet Hold"] = {
    "Lore: Dalaran's Violet Hold prison hides secrets awakened near the Tomb of Sargeras.",
    "Lore: Repaired after a Blue Dragonflight attack, the prison later housed Lich King servants.",
    "Lore: A shadowy threat strikes at the Kirin Tor from within during the Legion war.",
    "Trivia: Warcraft III: The Frozen Throne showed the Violet Hold as underground caves and jails.",
    "Trivia: Discolored tiles before Millificent Manastorm's cell hide a cavern, possibly an earlier plan.",
    "Note: Two bosses are randomly chosen; the third is Sael'orn or Fel Lord Betrug.",
},
["The MOTHERLODE!!"] = {
    "Lore: Mount Kajaro's eruption tore Kezan apart before the goblins began mining Azerite.",
    "Lore: The Venture Company betrayed the Bilgewater goblins for Azerite refining techniques.",
    "Lore: Trade Prince Gallywix sent adventurers to assassinate Mogul Razdunk and recover Azerite.",
    "Lore: Mogul Razdunk seeks the title of Trade Prince by weaponizing Azerite.",
    "Trivia: It was introduced at BlizzCon 2017 as the Kezan dungeon, and renamed several times.",
    "Trivia: Moira Thaurissan jokes that the name has too many exclamation points.",
    "Note: Horde take boats in, while the Alliance use a Dark Iron mole machine in Xibala.",
    "Note: Bosses are the Coin-Operated Crowd Pummeler, Azerokk, Rixxa Fluxflame and Mogul Razdunk.",
},
["Torghast, Tower of the Damned"] = {
    "Lore: Torghast is the Jailer's seat of power at the center of the Maw.",
    "Lore: It serves as an eternal prison for the most dangerous souls in the cosmos.",
    "Lore: Torghast's corridors shift constantly according to the Jailer's will.",
    "Lore: Freeing captives like Baine, Jaina, Thrall and Anduin is part of the story.",
    "Lore: Bolvar Fordragon in Oribos starts the quest chain that unlocks Torghast.",
    "Trivia: Its name is shared with an unrelated Scourge structure in the Ghostlands.",
    "Note: Layer bosses drop Soul Ash, which the Runecarver uses to craft legendary gear.",
    "Note: Ve'nari at her refuge trades Stygia for permanent Torghast upgrades.",
    "Note: Equipment and talent swaps are locked mid-run, except in Refuge of the Damned.",
    "Note: Brokers can be attacked after taking the Shoplifter blessing, dropping extra rewards.",
},
["Dawn of the Infinite"] = {
    "Lore: Dawn of the Infinite is an eight-boss megadungeon in the Temporal Conflux in Thaldraszus.",
    "Lore: The dormant Bronze Temple was reclaimed by the bronze dragonflight after millennia.",
    "Lore: Infinite dragonflight agents seek to twist the Timeways and bring about Murozond's rise.",
    "Lore: Necrotic energy from Galakrond's corpse revived the primal dragons of the Blight.",
    "Lore: Iridikron the Stonescaled is an Incarnate siphoning Galakrond's essence into an ancient vessel.",
    "Lore: Titan-Keeper Tyr has joined the infinite dragonflight in the altered timeline.",
    "Lore: Morchie is an alternate form of Chromie from a timeline where Murozond rose.",
    "Lore: Chrono-Lord Deios travels into the past to ensure Murozond rises.",
    "Note: An optional intro questline begins at the Seat of the Aspects in Valdrakken.",
    "Note: Time-Lost Battlefield pits you against Grommash or Anduin Lothar, depending on faction.",
},
["City of Threads"] = {
    "Lore: The City of Threads is the nerubian capital of the kingdom of Azj-Kahet.",
    "Lore: The city has been rebuilt over its own crumbling districts many times.",
    "Lore: Queen Ansurek formerly ruled the city, and its leadership is now unknown.",
    "Lore: Wealthy citizens and the queen's favorites live in hanging nests above the masses.",
    "Note: The City of Threads dungeon and the Nerub-ar Palace raid are both located here.",
    "Note: A flight master serves the city, but there are no portals.",
},
["Darkmaul Citadel"] = {
    "Lore: Darkmaul Citadel is an ogre stronghold led by Gor'groth.",
    "Lore: The citadel's architecture is distinctly Gorian, in the craftsmanship of the old ogre empire.",
    "Note: It lies in western Exile's Reach, with a dungeon inside and a questing area outside.",
    "Note: The citadel has strong walls, several catapults, a boar pen and a cooking pit.",
},
["Sporefall"] = {
    "Lore: The Fungarians of Sporefall nurtured a fungal giant far beyond its natural growth cycle.",
    "Lore: Rotmire is a brute whose spores can spark growth in the fungi around it.",
    "Lore: Sporefall is a Midnight raid set in Harandar, and Rotmire is its only boss.",
    "Note: Four weekly Delicious Sporesnacks are needed to make the Luminous Sporeglider.",
},
["The Blinding Vale"] = {
    "Lore: The Blinding Vale is where the Lightbloom first took root in Harandar.",
    "Lore: The Rutaani emerged from the Lightbloom and spread it in their wake.",
    "Lore: Orweyna struck at the Lightbloom after its defeat in Eversong to keep it in check.",
    "Trivia: During alpha, the dungeon was called Lightbloom Dungeon.",
    "Note: The entrance lies in the Tangleknot, inside the Blinding Bloom in southwestern Harandar.",
    "Note: Its four subzones are the Gilded Tangle, Luminous Garden, Warden's Retreat and Conviction's Crucible.",
},
["Voidscar Arena"] = {
    "Lore: A powerful entity holds creatures from across the cosmos captive, staging them like a circus.",
    "Lore: Adventurers must fight the captives for the entity's entertainment and their own survival.",
    "Note: The bosses are Taz'Rah, Atroxus and Charonus, who is the final boss.",
    "Note: The arena lies in Voidstorm, alongside Nexus-Point Xenas and The Voidspire.",
    "Note: Its subregions include Grasping Reach, Slayer's Rise, Pit of Spite, Sparring Grounds and The Husk.",
},
["Altar of Fangs"] = {
    "Lore: The Amani sealed the Vaults of Atal'Utek here with the Fang of Ula'tek.",
    "Lore: Only the cursed Fang of Ula'tek can unseal the great weapon the Amani imprisoned.",
    "Lore: Zul'jan entered the altar seeking to bring lost glory back to the Amani.",
    "Lore: Orweyna and Liadrin pursue Zul'jan into the accursed dungeon.",
    "Note: The altar lies on the Coiled Isle, and Zul'jan is the final boss after Rav'i and The Writhing Coil.",
    "Note: Its subzones include Ancient Burrow, Mutation Chambers, Sacrificial Approach and The Carnage Pit.",
},
["The Tidebound Grotto"] = {
    "Lore: The Tidebound Grotto is a submerged lair hidden beneath the waves of Atal'Utek.",
    "Lore: The naga sorceress Nymrissa Wavecaller bends the tides to conceal her domain and drown intruders.",
    "Note: The grotto lies in the waters of the Coiled Isle, and Nymrissa is its only boss.",
},
["Auchindoun"] = {
    "Lore: Auchindoun is a draenei mausoleum, built to shelter the souls of the dead.",
    "Lore: Maladaar created the Auchenai order to guard draenei souls on Draenor.",
    "Lore: Warlocks summoned Murmur, whose arrival blasted Auchindoun apart on Draenor.",
    "Lore: During the Outland invasion, four factions vied for control of the ruins.",
    "Lore: The Auchenai draenei have reclaimed Auchindoun and resumed caring for the souls of the dead.",
    "Trivia: Auchindoun was once announced as both a dungeon and a city.",
    "Trivia: Warcraft II's Fortress Auchindoun was later retconned.",
    "Note: The Outland ruins hold four five-player wings, each with its own bosses.",
},
["The Venomous Abyss"] = {
    "Lore: The Venomous Abyss is a Midnight raid on the Coiled Isle.",
    "Lore: Zul'jan freed the forgotten broods of Ula'tek from their prison, guided by Malacrass.",
    "Lore: Zul'jarra calls on Azeroth's champions to stop her brother before Ula'tek's weapon is unleashed.",
    "Note: Its eight encounters are split across four Raid Finder wings.",
    "Trivia: Several achievement names are playful, including Comforting Da Spirits and No Egg Scramble.",
},
["Battle for Mount Hyjal"] = {
    "Lore: The battle at Mount Hyjal ended the Third War between mortals and the Burning Legion.",
    "Lore: Wisps ignited Nordrassil's enchantments, and the explosion destroyed Archimonde.",
    "Lore: Malfurion Stormrage sounded the Horn of Cenarius to trigger the World Tree's explosion.",
    "Lore: Night elves, Alliance refugees and the New Horde united against the Legion.",
    "Lore: The battle cost the night elves their immortality when Nordrassil's enchantments were lost.",
    "Lore: Jaina Proudmoore left Hyjal and later founded Theramore in Dustwallow Marsh.",
    "Lore: The orcs settled Durotar after the battle and founded Orgrimmar.",
    "Lore: Medivh vanished after witnessing the victory, believing Azeroth no longer needed Guardians.",
    "Lore: The Lich King broke ties with the Burning Legion after the defeat at Hyjal.",
    "Lore: Archimonde's remains were left as a skeleton at the base of Nordrassil.",
    "Trivia: Kaz'rogal, unlike the other named demons here, does not appear in Warcraft III.",
    "Note: The battle is a time pocket reached from the Caverns of Time.",
},
["Trial of the Grand Crusader"] = {
    "Lore: Trial of the Grand Crusader is the heroic version of Trial of the Crusader.",
    "Lore: The raid sits in the Crusaders' Coliseum on the Argent Tournament Grounds.",
    "Lore: Anub'arak is a surprise fifth encounter that raids are dropped into.",
    "Lore: Lord Jaraxxus is a man'ari eredar lord of the Burning Legion.",
    "Note: Killing Acidmaw and Dreadscale within 10 seconds earns Not One, But Two Jormungars.",
},
["Hellfire Citadel"] = {
    "Lore: Blackhand built Hellfire Citadel as the Horde's new headquarters.",
    "Lore: The Shadow Council secretly watched the clans and reported to Gul'dan.",
    "Lore: Gul'dan made the clans drink Mannoroth's blood on a mountain near the Citadel.",
    "Lore: The land around the Citadel became a wasteland, giving the fortress its name.",
    "Lore: Ner'zhul's followers made the fortress the capital of the Horde of Draenor.",
    "Lore: The Alliance Expedition captured the Citadel, but Ner'zhul had already left.",
    "Lore: Kargath Bladefist and the Fel Horde later made the Citadel their base.",
    "Lore: Illidan's fel orcs held Magtheridon prisoner in the Citadel.",
    "Trivia: Warcraft II showed the Citadel on Draenor maps but never in missions.",
    "Trivia: The Citadel's design is angular and organic, like a beast with exposed bones.",
    "Note: Magtheridon's Lair is a 25-player raid, similar to Onyxia's Lair.",
},
["Trial of Valor"] = {
    "Lore: Odyn has been trapped in the Halls of Valor since Loken's betrayal.",
    "Lore: Helya schemes in the shadows to claim the souls of Odyn's valarjar champions.",
    "Lore: Odyn summons heroes arriving in Stormheim to face a final test.",
    "Lore: The final push descends into Helheim to confront Helya at her throne.",
    "Note: Guarm guards the passage to Helya's throne and must be slain first.",
    "Note: Enter via the Gates of Valor, reached by the southeast road from Valdisdall.",
},
["Alterac Valley"] = {
    "Lore: Gul'dan exiled the Frostwolf orcs to a hidden valley in Alterac.",
    "Lore: Drek'Thar led the Frostwolves after Thrall united the orc clans.",
    "Lore: The Stormpike dwarves arrived seeking resources and ancient titan relics.",
    "Lore: Generals Vanndar Stormpike and Drek'Thar lead the rival forces.",
    "Lore: After the Lich King's defeat, a truce paused the fighting in the valley.",
    "Lore: Ironforge's King Magni claimed the land as a sovereign imperative.",
    "Trivia: Alterac Valley was the only large-scale battleground until Isle of Conquest arrived.",
    "Trivia: Vanndar wrote a book titled The Frostwolf Artichoke: Tales of Stormpike Glory.",
    "Note: Killing the enemy General instantly wins the match for your side.",
    "Note: Freeing enemy-held Wing Commanders awards honor and a turn-in quest.",
},
["Warsong Gulch"] = {
    "Lore: Grom Hellscream's orcs cleared forest near the Gulch during the Third War.",
    "Lore: The Warsong Outriders keep deforesting the area despite Thrall's disapproval.",
    "Lore: The Silverwing Sentinels vow to drive every orc out of the Gulch.",
    "Lore: The dispute over Ashenvale's forests concerns one of the night elves' most important ancestral lands.",
    "Trivia: Warsong Gulch appears in the World of Warcraft Trading Card Game.",
    "Note: Flag carriers gain a stacking damage-taken debuff when both flags are held.",
    "Note: Mounting, stealthing or being killed makes the flag carrier drop the flag.",
},
["Arathi Basin"] = {
    "Lore: Arathi Basin is a mountain-rimmed valley rich in mines and fertile land.",
    "Lore: The League of Arathor seeks the basin for its Stormwind allies.",
    "Lore: The Defilers seek its resources to savage Lordaeron and secure the Undercity.",
    "Lore: The basin is a major staging point in the human-Forsaken war.",
    "Trivia: Its setting is meant to evoke the Scottish Highlands.",
    "Trivia: A parody MP3 riffs on Abbott and Costello's Who's on First skit.",
    "Note: The five resource nodes are the Farm, Stables, Blacksmith, Lumber Mill and Gold Mine.",
    "Note: Holding all five nodes yields far more resources than holding just four.",
},
["Eye of the Storm"] = {
    "Lore: Draenei seek the isle for its proximity to the naaru vessel Tempest Keep.",
    "Lore: Blood elves of Silvermoon covet the island for its rich energy deposits.",
    "Lore: Eye of the Storm floats high above Netherstorm, held together by mana storms.",
    "Trivia: Eye of the Storm was the first battleground with no open-world entrance.",
    "Trivia: A Trading Card Game card depicts Eye of the Storm.",
    "Note: Falling into the void between landmasses kills players after a short fall.",
},
["Strand of the Ancients"] = {
    "Lore: The 15 vs 15 battleground sat off Dragonblight's southern coast in Northrend.",
    "Lore: Horde and Alliance fought over a Titan relic inside an ancient citadel.",
    "Lore: The Valiance Expedition and Warsong Offensive represented the Alliance and Horde.",
    "Trivia: The battleground was originally called Sands of Ulduran during beta.",
    "Trivia: Its design is often described as a D-Day invasion scenario.",
    "Note: Winning in under four minutes is fairly common and earns Storm the Beach.",
    "Note: Seaforium bombs cannot be destroyed by turrets and can be carried while mounted.",
},
["Isle of Conquest"] = {
    "Lore: The Isle of Conquest sits off Northrend's coast near Icecrown.",
    "Lore: Horde and Alliance fight over the island's resources during the Lich King war.",
    "Lore: The 7th Legion and Kor'kron Guard fight on the Alliance and Horde sides.",
    "Lore: Overlord Agmar and Halford Wyrmbane are the Horde and Alliance generals.",
    "Note: It is a 40 vs 40 battleground won by defeating the enemy general.",
    "Note: Holding the Workshop unlocks Demolishers and, later, a Siege Engine.",
    "Note: Airship paratroopers can land in the enemy courtyard before its gates fall.",
    "Trivia: The battleground was added in patch 3.2.0 during Wrath of the Lich King.",
},
["Battle for Gilneas"] = {
    "Lore: Battle for Gilneas takes place on the northwestern coast of the Gilnean peninsula.",
    "Lore: Gilneas cut ties with the Alliance after the Second War, becoming independent.",
    "Lore: The Horde viewed the damaged nation as a key resource base for its war.",
    "Lore: The Forsaken had destroyed all their footholds in Gilneas before the battle.",
    "Trivia: The battleground was first designed for Gilneas City but reworked after playtesting.",
    "Trivia: The map's compass directions are inaccurate, placing the Greymane Wall along the east.",
    "Note: Capture the Mines, Lighthouse and Waterworks to earn resources over time.",
    "Note: The Overlook in the map center can decide control of the capture points.",
    "Note: The Double Rainbow achievement requires a gasp emote under the double rainbow.",
},
["Twin Peaks"] = {
    "Lore: Twin Peaks pits Wildhammer dwarves against Dragonmaw orcs in the Twilight Highlands.",
    "Lore: The Wildhammer clan originally built and owned the fortress city of Grim Batol.",
    "Lore: The Dragonmaw clan spent years working to enslave red dragons.",
    "Trivia: The battleground shares its name with the television series Twin Peaks.",
    "Trivia: The Fire, Walk With Me and White Lodge achievements reference the Twin Peaks series.",
    "Note: It plays like Warsong Gulch, a capture-the-flag battleground.",
    "Note: A single central bridge is the chokepoint, though the deep river can be crossed.",
    "Note: Outposts on either side of the river offer temporary character enhancements.",
},
["Temple of Kotmogu"] = {
    "Lore: Mogu left orbs of power behind in their ancient temples in Pandaria.",
    "Lore: The orbs are older than human royal bloodlines and orc clans.",
    "Trivia: The battleground was tentatively called Valley of Power when announced at BlizzCon 2011.",
    "Trivia: A planned scenario of the same name did not leave beta.",
    "Note: Players holding an orb cannot use their mount.",
    "Note: Scoring is highest at the center of the map and lower farther out.",
    "Note: Holding an orb in the center for 90 seconds earns the Powerball achievement.",
},
["Silvershard Mines"] = {
    "Lore: Silvershard Mines is set in a Venture Company goblin mine beneath Stranglethorn Vale.",
    "Lore: Alliance and Horde teams race for diamonds, which buy blades, ballistae and battle-gear.",
    "Lore: At BlizzCon 2011 the battleground was called Stranglethorn Diamond Mines, before being renamed.",
    "Trivia: The battleground's concept resembles the Payload mode in Team Fortress 2.",
    "Note: Carts move automatically, and track switches let you redirect them toward teammates.",
    "Note: You don't need control of a cart to switch its track.",
},
["Deepwind Gorge"] = {
    "Lore: Deepwind Gorge lies in the Valley of the Four Winds.",
    "Lore: It began as a resource race battleground before a later redesign.",
    "Trivia: The redesign was inspired by Arathi Basin, another 15v15 battleground.",
    "Trivia: The area is not to scale, much like Battle for Gilneas.",
    "Trivia: Placed on the real map, it would sit directly on top of Halfhill.",
    "Note: The five capture points are Market, Farm, Ruins, Shrine and Quarry.",
},
["Seething Shore"] = {
    "Lore: Seething Shore is a tropical island in the Veiled Sea.",
    "Lore: Azerite is erupting onto the island's surface, near Silithus.",
    "Lore: Alliance and Horde gunships hover over the island, which holds ogre ruins.",
    "Lore: Nathanos Blightcaller and Mathias Shaw oversee their factions' efforts here.",
    "Lore: A gnomish plane crashed on the island.",
    "Trivia: Seething Shore was first announced at BlizzCon 2017.",
    "Trivia: Most soldiers on the gunships above the shore previously came from Ashran.",
    "Note: Three Azerite nodes are active at once, and the first team to 1,500 wins.",
    "Note: Watch the sky for power-ups that can give your team an edge.",
},
["Deephaul Ravine"] = {
    "Lore: Deephaul Ravine debuted in The War Within as a 10v10 battleground.",
    "Lore: The Machine Speakers' Foreman Uzjax and the Unbound's Ruffious contest the crystals.",
    "Trivia: The two bases are modeled on the Earthenworks and Waterworks, and named after them.",
    "Trivia: The center resembles Ironhaul Station.",
    "Note: Deephaul Ravine lies in the Ringing Deeps.",
},
["Slayer's Rise"] = {
    "Lore: Slayer's Rise is a 40v40 epic battleground in Voidstorm.",
    "Lore: The Domanaar warlords Ziadan and Vidious are fighting for control of Voidstorm.",
    "Trivia: The battleground is inspired by Alterac Valley and Isle of Conquest.",
    "Trivia: Ziadan serves as the Alliance general, and Vidious as the Horde general.",
    "Note: Horde slay Vidious at Grief Spire, while the Alliance slay Ziadan at Hate Spire.",
    "Note: Master's Terrace has a dueling area and PvP vendors in the neutral hub.",
    "Note: The Voidscar Arena dungeon is found within Slayer's Rise.",
},
["Ring of Trials"] = {
    "Lore: The Ring of Trials is an ancient orcish proving ground, built with imperial ogre architecture.",
    "Trivia: Added in The Burning Crusade, it ranks among the game's first arenas.",
    "Trivia: A Trading Card Game card also bears the Ring of Trials name.",
    "Note: It sits southeast of Garadar in Nagrand, and is open to the outside world.",
    "Note: Four central columns help with line of sight and kiting.",
    "Note: Shadow Sight power-ups appear after five minutes, revealing stealthed players.",
},
["Circle of Blood Arena"] = {
    "Lore: The Circle of Blood Arena is also called Blade's Edge Arena.",
    "Lore: It was added in The Burning Crusade alongside Ring of Trials, among the first arenas.",
    "Lore: High King Maulgar watches from a throne and taunts players to fight each other.",
    "Trivia: A Nether Drake can be seen flying over the arena.",
    "Note: It lies north of Thunderlord Stronghold in Blade's Edge Mountains.",
    "Note: Stepping under the bridge can break line of sight from casters above.",
    "Note: Dead players can watch fights from the pit under the central bridge.",
},
["Ruins of Lordaeron"] = {
    "Lore: The Ruins of Lordaeron are the remains of the former capital of Lordaeron.",
    "Lore: The Scourge destroyed the city after Arthas betrayed his people.",
    "Lore: The ruins are haunted by the final events leading to King Terenas's death.",
    "Lore: The Forsaken later purged the blight and made the ruins their new capital.",
    "Lore: The Desolate Council was formed in the ruins' courtyard after the Amalgam's defeat.",
    "Trivia: The rounded southern wall appears based on terrain from a Warcraft II mission.",
    "Note: Detect Invisibility reveals the ghosts of Lordaeron's citizens haunting the courtyard.",
    "Note: Lordaeron's palace still stands, and once served as an entrance to the Undercity.",
},
["Dalaran Arena"] = {
    "Lore: The Dalaran Arena lies in the Underbelly of Dalaran in Northrend.",
    "Lore: It is also known as the Dalaran Sewers.",
    "Trivia: An un-instanced version of the arena lies beneath the Circle of Wills.",
    "Trivia: NPCs periodically act out brief 2v2 or 3v3 matches in the un-instanced arena.",
    "Note: Water shoots both teams out of the starting pipes shortly after the match begins.",
    "Note: A central pipe drops water at random, blocking line of sight.",
    "Note: Crates on the raised center's edges block line of sight and can interrupt spellcasting.",
},
["Tol'Viron Arena"] = {
    "Lore: Tol'viron Arena sits in Uldum and arrived with Mists of Pandaria.",
    "Lore: It is the sixth arena map, and the first new one since the Dalaran Sewers.",
    "Lore: The arena is a heavily modified version of the Ruins of Ammon.",
    "Trivia: Its layout is based on the simple Nagrand Arena design.",
    "Trivia: The only differences from Nagrand Arena are the art style and the pillar direction.",
},
["Tiger's Peak"] = {
    "Lore: Tiger's Peak is an arena in the Shado-Pan Monastery, atop Kun-Lai Summit.",
    "Lore: It is the seventh arena map, launched during Mists of Pandaria.",
    "Lore: Its setting is framed as a training ground of the Shado-Pan.",
    "Note: Looming tiger statues and fenced platforms can give players an advantage.",
},
["Ashamane's Fall"] = {
    "Lore: Ashamane's Fall is a small temple in northeastern Val'sharah.",
    "Lore: Ashamane defeated the demon Ronokon but died from his fel explosion.",
    "Lore: A shrine was built where Ashamane died, and Ashen druids keep watch over her fangs.",
    "Note: Leafbeard the Storied sometimes appears here to share War of the Ancients stories.",
    "Note: The arena contains non-targetable spectators such as Sylvan Striders and Sylvan Owls.",
},
["Black Rook Hold Arena"] = {
    "Lore: Black Rook Hold Arena sits outside Black Rook Hold in Val'sharah.",
    "Note: The subzone containing the arena is called Raven's Glory.",
    "Note: Spectators include Ghostly Spectators, Reanimated Archers, Kaldorei Windgryphs and Risen Sabers.",
},
["Hook Point"] = {
    "Lore: Hook Point is an upscale market where crime spills over from Dampwick Ward.",
