    "Note: It lies just southeast of the Proudmoore Barracks in Boralus.",
    "Note: Hook Point's brewers make Hook Point Schnapps and Hook Point Porter.",
    "Note: The Hook Point arena is actually in the Ashvane Company Yards.",
},
["The Mugambala"] = {
    "Lore: The Mugambala is an arena at the foot of sacred Mount Mugamba.",
    "Lore: Je'stry the Untamed set up the arena to train Rastari members.",
    "Lore: Horde forces under High Warlord Volrath were sent to train alongside Zandalari allies.",
    "Trivia: During beta, the arena was called Zandalar Arena and Zandalari Arena.",
    "Note: The Mugambala is the Horde location for the Dueler's Guild.",
},
["The Robodrome"] = {
    "Lore: During Operation: Mechagon, adventurers fought through the Robodrome into the lost city.",
